def run_flow_rules(
    context: StaticContext, selected: tuple[str, ...]
) -> dict[str, RuleRunState]:
    from sentinel.errors import InfrastructureError, SentinelError
    from sentinel.static.execution import check_deadline
    from sentinel.static.model import RuleRunState

    rules = tuple(rule for rule in selected if rule in FLOW_RULES)
    # ponytail: four workers only for large inputs; small scans avoid spawn cost.
    if (
        len(rules) < 2
        or (os.cpu_count() or 1) < 2
        or sum(len(file.source) for file in context.files.python_files)
        + sum(len(file.source) for file in context.files.typescript_files)
        < MIN_SOURCE_SIZE
    ):
        return {}
    # Parse once in the parent. Workers rebuild identity-keyed indexes, and their
    # rule traversals launch no subprocesses, so each worker can be reaped directly.
    trees = context.typescript_program.trees if context.files.typescript_files else {}
    check_deadline(context.deadline)
    processes: dict[str, subprocess.Popen[bytes]] = {}
    states = {}
    try:
        with (
            TemporaryDirectory(prefix="sentinel-static-") as directory,
            ExitStack() as stack,
        ):
            root = Path(directory)
            source = root / "input.pickle"
            source.write_bytes(
                pickle.dumps(
                    (context.configuration, context.files, context.deadline, trees)
                )
            )
            try:
                for rule in rules:
                    check_deadline(context.deadline)
                    log = stack.enter_context((root / f"{rule}.log").open("wb"))
                    processes[rule] = subprocess.Popen(
                        [
                            sys.executable,
                            "-I",
                            str(WORKER),
                            str(source),
                            str(root / f"{rule}.pickle"),
                            rule,
                        ],
                        cwd=WORKER.parent,
                        stdin=subprocess.DEVNULL,
                        stdout=log,
                        stderr=subprocess.STDOUT,
                    )
                for rule, process in processes.items():
                    process.wait(
                        timeout=max(0.001, context.deadline - time.monotonic())
                    )
                    if process.returncode:
                        detail = (root / f"{rule}.log").read_text(errors="replace")[
                            -2000:
                        ]
                        raise InfrastructureError(
                            f"{rule} static worker exited {process.returncode}: "
                            f"{detail}"
                        )
                    # Both files are private IPC produced by this scanner, never target
                    # inputs. Pickle retains the existing canonical internal types.
                    result = pickle.loads((root / f"{rule}.pickle").read_bytes())
                    if isinstance(result, SentinelError):
                        raise result
                    if not isinstance(result, RuleRunState):
                        raise InfrastructureError(
                            f"{rule} static worker returned invalid state"
                        )
                    states[rule] = result
                check_deadline(context.deadline)
            finally:
                for process in processes.values():
                    if process.poll() is None:
                        process.kill()
                for process in processes.values():
                    process.wait()
    except subprocess.TimeoutExpired as error:
        raise InfrastructureError(
            "static analysis timeout: deadline exceeded"
        ) from error
    except (OSError, pickle.UnpicklingError, EOFError) as error:
        raise InfrastructureError("static worker communication failed") from error
    return states

class StaticContext:
    configuration: LoadedConfiguration
    files: StaticFileSet
    deadline: float = float("inf")
    typescript_trees: dict[str, dict[str, Any]] | None = None

    @cached_property
    def python_program(self) -> PythonProgram:
        from sentinel.static.discovery import PythonProgram

        return PythonProgram(self.files.python_files, deadline=self.deadline)

    @cached_property
    def python_http_handlers(self) -> tuple[HTTPBinding, ...]:
        from sentinel.static.http_discovery import handlers

        return handlers(self.python_program)

    @cached_property
    def typescript_http_handlers(self) -> tuple[TypeScriptHTTPBinding, ...]:
        from sentinel.static.http_discovery import typescript_handlers

        return typescript_handlers(self.typescript_program)

    @cached_property
    def typescript_program(self) -> TypeScriptProgram:
        from sentinel.static.typescript_discovery import TypeScriptProgram
        from sentinel.static.typescript_modules import TypeScriptModules

        workspace = self.configuration.workspace
        return TypeScriptProgram(
            self.files.typescript_files,
            deadline=self.deadline,
            trees=self.typescript_trees,
            modules=TypeScriptModules(
                self.configuration.scan_root,
                self.files.config_files,
                workspace.members if workspace else (".",),
            ),
        )

class TypeScriptProgram:
    def __init__(
        self,
        files: tuple[TypeScriptSourceFile, ...],
        *,
        deadline: float,
        modules: TypeScriptModules | None = None,
        trees: dict[str, dict[str, Any]] | None = None,
    ) -> None:
        self.files = {file.relative_path: file for file in files}
        self.deadline = deadline
        self.modules = modules
        self.trees: dict[str, dict[str, Any]] = {}
        self.bindings: dict[str, dict[str, list[dict[str, Any]]]] = {}
        self.exports: dict[str, set[str]] = {}
        self.class_attributes: dict[int, list[dict[str, Any]]] = {}
        self.source_ranges: OrderedDict[
            tuple[int, int], tuple[Any, TypeScriptSourceFile, SourceRange]
        ] = OrderedDict()
        self.warnings: list[ReportWarning] = modules.warnings if modules else []
        for file in files:
            tree = (
                parse_typescript(file, deadline=deadline)
                if trees is None
                else trees[file.relative_path]
            )
            self.trees[file.relative_path] = tree
            bindings: dict[str, list[dict[str, Any]]] = defaultdict(list)
            exports: set[str] = set()
            for node in tree["Pr"]:
                if "DefStmt" in node:
                    entity, definition = node["DefStmt"]
                    if "ClassDef" in definition:
                        self.class_attributes[id(definition)] = entity.get("attrs", [])
                    name = name_of(entity["name"])
                    if name:
                        variable = definition.get("VarDef", {})
                        bindings[name].append(
                            (variable.get("vinit") or {}).get("some", definition)
                        )
                directive = node.get("DirectiveStmt", {}).get("d", {})
                if "ImportFrom" in directive:
                    _, module, names = directive["ImportFrom"]
                    for item in names:
                        if "Aliased" in item:
                            original, alias = item["Aliased"]
                            local = alias[0][0]
                        elif "Direct" in item:
                            original, _ = item["Direct"]
                            local = original[0]
                        else:
                            continue
                        bindings[local].append(
                            {"import": (module["FileName"][0], original[0])}
                        )
                elif "ImportAs" in directive:
                    _, module, alias = directive["ImportAs"]
                    if alias:
                        bindings[alias["some"][0][0]].append(
                            {"import": (module["FileName"][0], "")}
                        )
                other = directive.get("OtherDirective")
                if other and other[0][0] == "Export":
                    exports.update(item["I"][0] for item in other[1] if "I" in item)
            # A write anywhere can rebind a module-level handler at runtime.
            for node in walk(tree):
                assignment = node.get("Assign", node.get("AssignOp"))
                if assignment:
                    name = name_of(assignment[0])
                    if name and name.split(".")[0] in bindings:
                        bindings[name.split(".")[0]].append({"rebound": True})
            self.bindings[file.relative_path] = dict(bindings)
            self.exports[file.relative_path] = exports

    def property(
        self,
        symbol: TypeScriptSymbol,
        name: str,
        seen: frozenset[tuple[str, str]] = frozenset(),
    ) -> TypeScriptSymbol | None:
        if "Record" not in symbol.node:
            return None
        matches = []
        for field in symbol.node["Record"][1]:
            definition = field.get("F", {}).get("DefStmt")
            if not definition or name_of(definition[0]["name"]) is None:
                self.unresolved(symbol.file, "computed or spread object member")
                return None
            if name_of(definition[0]["name"]) == name:
                matches.append(definition[1])
        if len(matches) != 1:
            return None
        definition = matches[0]
        value = (definition.get("FieldDefColon", {}).get("vinit") or {}).get(
            "some", definition
        )
        return self.resolve_node(symbol.file, value, seen=seen)

    def literal(self, symbol: TypeScriptSymbol | None, depth: int = 0) -> str | None:
        if symbol is None or depth >= 64:
            return None
        string = symbol.node.get("L", {}).get("String")
        if string:
            return str(string[1][0])
        call = symbol.node.get("Call")
        if call:
            operation = call[0].get("Special", [{}])[0]
            if isinstance(operation, dict) and (
                "ConcatString" in operation or operation.get("Op") == "Plus"
            ):
                values = [
                    self.literal(self.resolve_node(symbol.file, arg["Arg"]), depth + 1)
                    for arg in call[1][1]
                    if "Arg" in arg
                ]
                if values and all(value is not None for value in values):
                    return "".join(value for value in values if value is not None)
        return None

    def listed_tools(self) -> tuple[TypeScriptSymbol, ...]:
        """Recover metadata returned to the SDK's low-level tools/list schema."""
        found = []
        for file in self.files.values():
            for node in walk(self.trees[file.relative_path]):
                call = node.get("Call")
                if not call or not (name_of(call[0]) or "").endswith(
                    ".setRequestHandler"
                ):
                    continue
                args = [item["Arg"] for item in call[1][1] if "Arg" in item]
                if len(args) != 2:
                    continue
                schema = self.resolve_node(file, args[0])
                if not schema or schema.external != (
                    "@modelcontextprotocol/sdk/types.js.ListToolsRequestSchema"
                ):
                    continue
                handler = self.resolve_node(file, args[1])
                if not handler or not handler.function:
                    self.unresolved(file, "tools/list handler")
                    continue
                for returned in walk(handler.function["fbody"]):
                    if "Return" not in returned:
                        continue
                    value = (returned["Return"][1] or {}).get("some")
                    result = self.resolve_node(handler.file, value) if value else None
                    listing = self.property(result, "tools") if result else None
                    if listing is None or "Container" not in listing.node:
                        self.unresolved(file, "tools/list metadata")
                        continue
                    for item in listing.node["Container"][1][1]:
                        metadata = self.resolve_node(listing.file, item)
                        if metadata and "Record" in metadata.node:
                            found.append(metadata)
                        else:
                            self.unresolved(listing.file, "tools/list entry")
        return tuple(found)

    def tools(self) -> tuple[TypeScriptBinding, ...]:
        found: list[TypeScriptBinding] = []
        for file in self.files.values():
            for node in walk(self.trees[file.relative_path]):
                check_deadline(self.deadline)
                if "New" in node:
                    _, type_, _, arguments = node["New"]
                    constructor_name = name_of(type_.get("t", {}).get("TyExpr", {}))
                    if (
                        not constructor_name
                        or constructor_name.split(".")[0]
                        not in self.bindings[file.relative_path]
                    ):
                        continue
                    constructor = self.resolve_node(
                        file, type_.get("t", {}).get("TyExpr", {})
                    )
                    if (
                        not constructor
                        or constructor.external != "@mastra/mcp.MCPServer"
                    ):
                        continue
                    args = [item["Arg"] for item in arguments[1] if "Arg" in item]
                    config = self.resolve_node(file, args[0]) if args else None
                    tools = self.property(config, "tools") if config else None
                    if tools and "Record" in tools.node:
                        for field in tools.node["Record"][1]:
                            definition = field.get("F", {}).get("DefStmt")
                            name = (
                                name_of(definition[0]["name"]) if definition else None
                            )
                            tool = self.property(tools, name) if name else None
                            if tool:
                                found.append(
                                    TypeScriptBinding(
                                        name,
                                        TypeScriptSymbol(file, node),
                                        self.property(tool, "execute"),
                                        self.property(tool, "parameters"),
                                        self.property(tool, "description"),
                                    )
                                )
                    else:
                        self.unresolved(file, "MCPServer tools")
                if "Call" not in node:
                    continue
                callee, arguments = node["Call"]
                name = name_of(callee)
                if not name or not name.endswith(
                    (".registerTool", ".tool", ".setRequestHandler")
                ):
                    continue
                receiver_name, _, method = name.rpartition(".")
                receiver = self.resolve(file, receiver_name)
                if not receiver or "New" not in receiver.node:
                    continue
                constructor_expression = (
                    receiver.node["New"][1].get("t", {}).get("TyExpr", {})
                )
                constructor = self.resolve_node(receiver.file, constructor_expression)
                if not constructor or constructor.external not in {
                    "@modelcontextprotocol/sdk/server/mcp.js.McpServer",
                    "@modelcontextprotocol/sdk/server/index.js.Server",
                }:
                    continue
                args = [
                    self.resolve_node(file, item["Arg"]) if "Arg" in item else None
                    for item in arguments[1]
                ]
                if len(args) < 2:
                    self.unresolved(file, name)
                    continue
                if method == "setRequestHandler":
                    if (
                        args[0]
                        and args[0].external
                        == "@modelcontextprotocol/sdk/types.js.CallToolRequestSchema"
                    ):
                        found.append(
                            TypeScriptBinding(
                                None, TypeScriptSymbol(file, node), args[1], None, None
                            )
                        )
                    continue
                tool_name = self.literal(args[0])
                config = args[1]
                if method == "registerTool":
                    schema = self.property(config, "inputSchema") if config else None
                    description = (
                        self.property(config, "description") if config else None
                    )
                    handler = args[2] if len(args) == 3 else None
                else:
                    middle = args[1:-1]
                    description = (
                        middle.pop(0)
                        if middle and self.literal(middle[0]) is not None
                        else None
                    )
                    schema = middle[0] if middle else None
                    handler = args[-1]
                found.append(
                    TypeScriptBinding(
                        tool_name,
                        TypeScriptSymbol(file, node),
                        handler,
                        schema,
                        description,
                    )
                )
        from sentinel.static.typescript_registration_flow import factory_tools

        wrapped = factory_tools(self)
        registrations = {id(tool.registration.node) for tool in wrapped}
        return (
            tuple(
                tool
                for tool in found
                if id(tool.registration.node) not in registrations
            )
            + wrapped
        )

    def source_range(self, node: Any, file: TypeScriptSourceFile) -> SourceRange:
        check_deadline(self.deadline)
        # Source syntax stays immutable within a program. Retain both objects so
        # identity reuse cannot confuse a synthetic node or another source snapshot.
        key = (id(node), id(file))
        if key not in self.source_ranges:
            self.source_ranges[key] = (node, file, source_range(node, file))
            # ponytail: bound retained locations; evicted nodes are revalidated.
            if len(self.source_ranges) > 4096:
                self.source_ranges.popitem(last=False)
        self.source_ranges.move_to_end(key)
        return self.source_ranges[key][2]

    def text(self, file: TypeScriptSourceFile, node: Any) -> str:
        location = self.source_range(node, file)
        lines = file.source.splitlines(keepends=True)
        start = (
            sum(map(len, lines[: location.start_line - 1])) + location.start_column - 1
        )
        end = sum(map(len, lines[: location.end_line - 1])) + location.end_column - 1
        return file.source[start:end]

    def unresolved(self, file: TypeScriptSourceFile, name: str) -> None:
        warning = ReportWarning(
            code="static_binding_unresolved",
            message=f"{file.relative_path}: cannot resolve TypeScript binding {name!r}",
        )
        if warning not in self.warnings:
            self.warnings.append(warning)

    def resolve(
        self,
        file: TypeScriptSourceFile,
        name: str,
        seen: frozenset[tuple[str, str]] = frozenset(),
    ) -> TypeScriptSymbol | None:
        check_deadline(self.deadline)
        key = (file.relative_path, name)
        if key in seen or len(seen) >= 64:
            self.unresolved(file, name)
            return None
        first, _, rest = name.partition(".")
        nodes = self.bindings[file.relative_path].get(first, [])
        if len(nodes) != 1:
            self.unresolved(file, name)
            return None
        return self.resolve_node(file, nodes[0], rest, seen | {key})

    def resolve_node(
        self,
        file: TypeScriptSourceFile,
        node: dict[str, Any],
        rest: str = "",
        seen: frozenset[tuple[str, str]] = frozenset(),
    ) -> TypeScriptSymbol | None:
        check_deadline(self.deadline)
        if "Await" in node:
            return self.resolve_node(file, node["Await"][1], rest, seen)
        call = node.get("Call")
        if call and name_of(call[0]) == "import" and len(call[1][1]) == 1:
            module = self.literal(TypeScriptSymbol(file, call[1][1][0].get("Arg", {})))
            if module is None or not module.startswith("."):
                self.unresolved(file, "nonliteral or external dynamic import")
                return None
            return self.resolve_node(file, {"import": (module, "")}, rest, seen)
        if "import" in node:
            module, imported = node["import"]
            target = ".".join(part for part in (imported, rest) if part)
            local, bases = (
                self.modules.resolve(file.relative_path, module)
                if self.modules is not None
                else (
                    module.startswith("."),
                    (
                        posixpath.normpath(
                            posixpath.join(
                                posixpath.dirname(file.relative_path), module
                            )
                        ),
                    ),
                )
            )
            if not local:
                # These Node default exports are the built-in module object.
                if imported == "default" and module.removeprefix("node:") in {
                    "fs",
                    "fs/promises",
                    "path",
                    "path/posix",
                    "path/win32",
                    "child_process",
                    "net",
                }:
                    target = rest
                return TypeScriptSymbol(
                    file, node, module + ("." + target if target else "")
                )
            included_paths = set()
            for base in bases:
                if base == ".." or base.startswith("../") or base.startswith("/"):
                    self.unresolved(file, module)
                    return None
                stem, extension = posixpath.splitext(base)
                candidates = {base}
                if extension in {".js", ".mjs", ".cjs"}:
                    candidates.update(
                        stem + ext for ext in (".ts", ".mts", ".cts", ".tsx")
                    )
                elif not extension:
                    candidates.update(
                        base + ext for ext in (".ts", ".mts", ".cts", ".tsx")
                    )
                    candidates.update(
                        base + "/index" + ext for ext in (".ts", ".mts", ".cts", ".tsx")
                    )
                matches = candidates.intersection(self.files)
                if len(matches) != 1:
                    self.unresolved(file, module + ":" + target)
                    return None
                included_paths.update(matches)
            included = [self.files[path] for path in sorted(included_paths)]
            if len(included) != 1:
                self.unresolved(file, module + ":" + target)
                return None
            if not target:
                return TypeScriptSymbol(file, node)
            if target.split(".")[0] not in self.exports[included[0].relative_path]:
                self.unresolved(file, module + ":" + target)
                return None
            return self.resolve(included[0], target, seen)
        alias = name_of(node)
        if alias:
            return self.resolve(file, alias + ("." + rest if rest else ""), seen)
        if rest and "Record" in node:
            first, _, tail = rest.partition(".")
            member = self.property(TypeScriptSymbol(file, node), first, seen)
            if member:
                return self.resolve_node(member.file, member.node, tail, seen)
        if not rest:
            return TypeScriptSymbol(file, node)
        self.unresolved(file, rest)
        return None

class RegistrationFlow(TypeScriptPathFlow):
    def __init__(self, program: TypeScriptProgram, factory: TypeScriptSymbol) -> None:
        super().__init__(program, RuleRunState())
        self.factory = factory
        self.values: dict[str, TypeScriptSymbol] = {}
        self.found: list[TypeScriptBinding] = []

    def expression(
        self, file: TypeScriptSourceFile, node: Any, env: dict[str, Value]
    ) -> Value:
        result = super().expression(file, node, env)
        if isinstance(node, dict) and any(
            key in node for key in ("L", "Record", "Call")
        ):
            self.values.setdefault(result.key, TypeScriptSymbol(file, node))
        return result

    def registered(
        self,
        file: TypeScriptSourceFile,
        node: dict[str, Any],
        args: list[Value],
        env: dict[str, Value],
    ) -> None:
        if len(args) != 3:
            self.program.unresolved(file, "factory registration arguments")
            return
        config = self.object_fields(args[1], env)
        self.found.append(
            TypeScriptBinding(
                self.program.literal(self.values.get(args[0].key)),
                self.call_sites[0] if self.call_sites else TypeScriptSymbol(file, node),
                self.callables.get(args[2].key),
                self.values.get(config.get("inputSchema", Value()).key),
                self.values.get(config.get("description", Value()).key),
                self.factory,
                TypeScriptSymbol(file, node),
            )
        )

def factory_tools(program: TypeScriptProgram) -> tuple[TypeScriptBinding, ...]:
    found = []
    for path, tree in program.trees.items():
        # Follow actual module construction of included classes. Merely declaring
        # an unused class does not register a tool.
        if not any(
            "ClassDef" in node
            or (
                "New" in node
                and (
                    constructor := program.resolve_node(
                        program.files[path],
                        node["New"][1].get("t", {}).get("TyExpr", {}),
                    )
                )
                is not None
                and "ClassDef" in constructor.node
            )
            for node in walk(tree)
        ):
            continue
        initializer = TypeScriptSymbol(program.files[path], tree)
        flow = RegistrationFlow(program, initializer)
        flow.initialize(initializer)
        found.extend(flow.found)
        program.warnings.extend(
            w for w in flow.state.warnings if w not in program.warnings
        )
    functions = {
        id(declarations[0]): TypeScriptSymbol(program.files[path], declarations[0])
        for path, bindings in program.bindings.items()
        for declarations in bindings.values()
        if len(declarations) == 1
        and TypeScriptSymbol(program.files[path], declarations[0]).function is not None
    }
    calls: dict[int, set[int]] = {}
    roots: list[TypeScriptSymbol] = []
    for identity, symbol in functions.items():
        check_deadline(program.deadline)
        calls[identity] = {
            id(target.node)
            for node in walk(symbol.node)
            if "Call" in node
            and (name_of(node["Call"][0]) or "").split(".")[0]
            in program.bindings[symbol.file.relative_path]
            for target in [program.resolve_node(symbol.file, node["Call"][0])]
            if target and target.function
        }
    for path, tree in program.trees.items():
        for statement in tree["Pr"]:
            if "ExprStmt" not in statement:
                continue
            for node in walk(statement):
                call = node.get("Call")
                if not call or call[1][1]:
                    continue
                name = name_of(call[0])
                if not name or name not in program.bindings[path]:
                    continue
                resolved = program.resolve(program.files[path], name)
                if (
                    resolved
                    and resolved.function
                    and not resolved.function["fparams"][1]
                ):
                    roots.append(resolved)
    reachable: dict[int, set[int]] = {}
    for root in roots:
        pending = [id(root.node)]
        seen: set[int] = set()
        while pending:
            check_deadline(program.deadline)
            identity = pending.pop()
            if identity not in seen:
                seen.add(identity)
                pending.extend(calls.get(identity, ()))
        reachable[id(root.node)] = seen
    for path, bindings in program.bindings.items():
        file = program.files[path]
        for declarations in bindings.values():
            if len(declarations) != 1:
                continue
            factory = TypeScriptSymbol(file, declarations[0])
            if factory.function is None:
                continue
            constructors = [
                program.resolve_node(
                    file, node["New"][1].get("t", {}).get("TyExpr", {})
                )
                for node in walk(factory.node)
                if "New" in node
            ]
            if not any(
                constructor
                and constructor.external
                in {
                    "@modelcontextprotocol/sdk/server/mcp.js.McpServer",
                    "@modelcontextprotocol/sdk/server/index.js.Server",
                }
                for constructor in constructors
            ):
                continue
            initializers = [
                root for root in roots if id(factory.node) in reachable[id(root.node)]
            ] or [factory]
            for initializer in initializers:
                flow = RegistrationFlow(program, initializer)
                flow.function(initializer, [])
                found.extend(flow.found)
                program.warnings.extend(
                    warning
                    for warning in flow.state.warnings
                    if warning not in program.warnings
                )
    return tuple(found)

def analyze(
    program: TypeScriptProgram,
    state: RuleRunState,
    *,
    flow: TypeScriptPathFlow | None = None,
    entries: tuple[TypeScriptBinding | TypeScriptHTTPBinding, ...] | None = None,
) -> None:
    flow = flow or TypeScriptPathFlow(program, state)
    factories: set[tuple[bool, int]] = set()
    for tool in program.tools() if entries is None else entries:
        initializer = (
            tool.initializer
            if isinstance(tool, TypeScriptHTTPBinding)
            else tool.factory
        )
        if initializer is not None:
            identity = (isinstance(tool, TypeScriptHTTPBinding), id(initializer.node))
            if identity not in factories:
                factories.add(identity)
                if isinstance(tool, TypeScriptHTTPBinding):
                    type(flow)(program, state).http_initialize(initializer)
                else:
                    flow.initialize(initializer)
            continue
        location = program.source_range(tool.registration.node, tool.registration.file)
        state.visit(tool.registration.file.relative_path, location)
        handler = tool.handler
        if handler is None or handler.function is None:
            flow.warning(
                tool.registration.file,
                tool.registration.node,
                "unresolved tool handler",
            )
            continue
        state.visit(
            handler.file.relative_path, program.source_range(handler.node, handler.file)
        )
        args = [
            Value(
                sources=frozenset(
                    {
                        "http:request"
                        if isinstance(tool, TypeScriptHTTPBinding)
                        else str(index)
                    }
                )
                if index == 0
                else frozenset(),
                key=f"{handler.file.relative_path}:{location}:{index}",
                locations=frozenset(
                    {(tool.registration.file.relative_path, location.start_line)}
                ),
            )
            for index, _ in enumerate(handler.function["fparams"][1])
        ]
        flow.function(handler, args)
    state.warnings.extend(program.warnings)

class TypeScriptModules:
    def __init__(
        self, root: Path, configs: tuple[Path, ...], members: tuple[str, ...]
    ) -> None:
        self.packages: dict[str, list[tuple[str, dict[str, Any]]]] = {}
        self.warnings: list[ReportWarning] = []
        self.config_paths = {
            path.relative_to(root).as_posix(): path for path in configs
        }
        self.option_cache: dict[str, dict[str, Any] | None] = {}
        for path in configs:
            if path.name not in {"package.json", "tsconfig.json"}:
                continue
            relative = path.relative_to(root).as_posix()
            directory = posixpath.dirname(relative) or "."
            try:
                value = json.loads(_devcontainer_json(path.read_text(encoding="utf-8")))
            except (OSError, ValueError) as error:
                raise ConfigurationError(
                    f"cannot parse configuration {relative}"
                ) from error
            if not isinstance(value, dict):
                raise ConfigurationError(f"configuration {relative} must be an object")
            if (
                path.name == "package.json"
                and directory in members
                and isinstance(value.get("name"), str)
            ):
                self.packages.setdefault(value["name"], []).append((directory, value))

    def _options(
        self, name: str, seen: frozenset[str] = frozenset()
    ) -> dict[str, Any] | None:
        if name in seen or len(seen) >= 64 or name not in self.config_paths:
            return None
        if name in self.option_cache:
            return self.option_cache[name]
        path = self.config_paths[name]
        try:
            config = json.loads(_devcontainer_json(path.read_text(encoding="utf-8")))
        except (OSError, ValueError) as error:
            raise ConfigurationError(f"cannot parse configuration {name}") from error
        if not isinstance(config, dict):
            raise ConfigurationError(f"configuration {name} must be an object")
        directory = posixpath.dirname(name) or "."
        merged: dict[str, Any] = {}
        parents = config.get("extends", [])
        parents = [parents] if isinstance(parents, str) else parents
        if not isinstance(parents, list):
            return None
        for parent in parents:
            if not isinstance(parent, str):
                return None
            target = local_path(directory, parent) if parent.startswith(".") else None
            if (
                target not in self.config_paths
                and target is not None
                and target + ".json" in self.config_paths
            ):
                target += ".json"
            if target not in self.config_paths:
                warning = ReportWarning(
                    code="static_typescript_configuration_unresolved",
                    message=(
                        f"{name}: inherited configuration {parent!r} was not applied "
                        "because it is outside included source; imports use only "
                        "available local settings and declared package names"
                    ),
                )
                if warning not in self.warnings:
                    self.warnings.append(warning)
                continue
            assert target is not None
            options = self._options(target, seen | {name})
            if options is None:
                return None
            merged.update(options)
        options = config.get("compilerOptions", {})
        if not isinstance(options, dict):
            return None
        if "baseUrl" in options:
            base = options["baseUrl"]
            origin = local_path(directory, base) if isinstance(base, str) else None
            if origin is None:
                return None
            merged["baseUrl"] = origin
        if "paths" in options:
            merged.update(paths=options["paths"], paths_origin=directory)
        self.option_cache[name] = merged
        return merged

    def resolve(self, source: str, module: str) -> tuple[bool, tuple[str, ...]]:
        """Return local ownership and candidate paths; an empty local set is unknown."""
        if module.startswith("."):
            path = local_path(posixpath.dirname(source), module)
            return True, (path,) if path is not None else ()
        directory = posixpath.dirname(source) or "."
        while True:
            config_path = posixpath.normpath(posixpath.join(directory, "tsconfig.json"))
            if config_path in self.config_paths:
                options = self._options(config_path)
                if options is None:
                    return True, ()
                mappings = options.get("paths", {})
                if not isinstance(mappings, dict):
                    return True, ()
                mapped = _mapped(mappings, module)
                origin = options.get("baseUrl", options.get("paths_origin", directory))
                if mapped:
                    targets, wildcard = mapped
                    if (
                        origin is None
                        or not isinstance(targets, list)
                        or not all(isinstance(target, str) for target in targets)
                    ):
                        return True, ()
                    paths = [
                        local_path(origin, target.replace("*", wildcard))
                        for target in targets
                    ]
                    if any(path is None for path in paths):
                        return True, ()
                    return True, tuple(path for path in paths if path is not None)
                break
            if directory == ".":
                break
            directory = posixpath.dirname(directory) or "."
        parts = module.split("/")
        count = 2 if module.startswith("@") else 1
        name, subpath = "/".join(parts[:count]), "/".join(parts[count:])
        packages = self.packages.get(name)
        if packages is None:
            return False, ()
        if len(packages) != 1:
            return True, ()
        directory, package = packages[0]
        if "exports" in package:
            exports = package["exports"]
            key = "./" + subpath if subpath else "."
            if isinstance(exports, dict) and any(k.startswith(".") for k in exports):
                mapped = _mapped(exports, key)
                if mapped is None:
                    return True, ()
                exported, wildcard = mapped
            elif not subpath:
                exported, wildcard = exports, ""
            else:
                return True, ()
            targets = self._export_targets(exported)
            if targets is None:
                return True, ()
            targets = [target.replace("*", wildcard) for target in targets]
            if any(
                not target.startswith("./")
                or ".." in target.split("/")
                or "node_modules" in target.split("/")
                for target in targets
            ):
                return True, ()
        elif subpath:
            targets = ["./" + subpath]
        else:
            targets = [package.get("main", "./index")]
            if not all(isinstance(target, str) for target in targets):
                return True, ()
        paths = [local_path(directory, target) for target in targets]
        if any(path is None for path in paths):
            return True, ()
        return True, tuple(dict.fromkeys(path for path in paths if path is not None))

    @staticmethod
    def _export_targets(value: Any) -> list[str] | None:
        if isinstance(value, str):
            return [value]
        if isinstance(value, dict):
            # Do not use declaration-only `types` as executable handler evidence.
            targets = []
            for key, child in value.items():
                if key in {"types", "require"}:
                    continue
                if key not in {"import", "node", "default"}:
                    return None
                resolved = TypeScriptModules._export_targets(child)
                if resolved is None:
                    return None
                targets.extend(resolved)
            return targets or None
        return None
